  font-size: 1.2rem;
  font-weight: 400;
  line-height: 2;
  margin-bottom: 3rem;
}

.buttons {
  display: flex;
  flex-direction: row;
  gap: 1rem;
}

.button {
  font-size: 1.2rem;
  font-weight: 700;
  text-decoration: none;
  padding: 1.2rem 1.5rem;
  border-radius: 10px;
}

.button-filled {
  color: black;
  background-color: #ffcc00;
  border: 2px solid #ffcc00;

  transition: all 0.2s ease-in-out;
}

.button-filled:hover {
  filter: brightness(0.95);
}

.button-outlined {
  color: black;
  background-color: transparent;
  border: 2px solid #ffcc00;

  transition: all 0.2s ease-in-out;
}

.button-outlined:hover {
  filter: brightness(0.95);
}

code {
