datasource db {
  provider = "sqlite"
  // Wasp requires that the url is set to the DATABASE_URL environment variable.
  url      = env("DATABASE_URL")
}

// Wasp requires the `prisma-client-js` generator to be present.
generator client {
  provider = "prisma-client-js"
}

model User {
  id        Int         @id @default(autoincrement())
  role      String      @default("ANALYST")
  documents Document[]
  auditLogs AuditLog[]
}

model Document {
  id      Int    @id @default(autoincrement())
  title   String
  content String
  ownerId Int
  owner   User   @relation(fields: [ownerId], references: [id])
}

model AuditLog {
  id         Int      @id @default(autoincrement())
  action     String
  entityName String
  entityId   Int
  userId     Int
  user       User     @relation(fields: [userId], references: [id])
  timestamp  DateTime @default(now())
  payload    String
}

import { defineUserSignupFields } from "wasp/server/auth";

export const userSignupFields = defineUserSignupFields({
  role: async (data) => {
    const role = data.role;
    const validRoles = ["ANALYST", "MANAGER", "ADMIN"];
    if (typeof role !== "string" || !validRoles.includes(role)) {
      return "ANALYST";
    }
    return role;
  },
});

import type { OnBeforeSignupHook } from "wasp/server/auth";

export const onBeforeSignup: OnBeforeSignupHook = async ({
  providerId,
  prisma,
  req,
}) => {
  // For usernameAndPassword auth, the providerUserId is the username
  const username = providerId.providerUserId;

  // Check if the user is trying to sign up with ADMIN role
  // We need to check the request body for the role field
  if (req.body) {
    const role = req.body.role;
    if (role === "ADMIN") {
      if (!username.endsWith("_admin")) {
        throw new Error(
          "Users signing up with ADMIN role must have a username ending with '_admin'"
        );
      }
    }
  }
};

import type { GetDocuments, GetAuditLogs } from "wasp/server/operations";
import { HttpError } from "wasp/server";

export const getDocuments: GetDocuments = async (_args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Authentication required");
  }
  // All authenticated users (ANALYST, MANAGER, ADMIN) can view documents
  return context.entities.Document.findMany({
    include: { owner: true },
  });
};

export const getAuditLogs: GetAuditLogs = async (_args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Authentication required");
  }
  // Only ADMIN can view audit logs
  if (context.user.role !== "ADMIN") {
    throw new HttpError(403, "Only ADMIN users can view audit logs");
  }
  return context.entities.AuditLog.findMany({
    include: { user: true },
    orderBy: { timestamp: "desc" },
  });
};

import type {
  CreateDocument,
  UpdateDocument,
  DeleteDocument,
} from "wasp/server/operations";
import { HttpError } from "wasp/server";

export const createDocument: CreateDocument<
  { title: string; content: string },
  void
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Authentication required");
  }
  // Only MANAGER and ADMIN can create documents
  if (context.user.role !== "MANAGER" && context.user.role !== "ADMIN") {
    throw new HttpError(403, "Only MANAGER and ADMIN users can create documents");
  }

  const doc = await context.entities.Document.create({
    data: {
      title: args.title,
      content: args.content,
      ownerId: context.user.id,
    },
  });

  // Create audit log entry
  await context.entities.AuditLog.create({
    data: {
      action: "CREATE",
      entityName: "Document",
      entityId: doc.id,
      userId: context.user.id,
      payload: JSON.stringify({ title: args.title, content: args.content }),
    },
  });
};

export const updateDocument: UpdateDocument<
  { id: number; title: string; content: string },
  void
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Authentication required");
  }
  // Only MANAGER and ADMIN can update documents
  if (context.user.role !== "MANAGER" && context.user.role !== "ADMIN") {
    throw new HttpError(403, "Only MANAGER and ADMIN users can update documents");
  }

  await context.entities.Document.update({
    where: { id: args.id },
    data: {
      title: args.title,
      content: args.content,
    },
  });

  // Create audit log entry
  await context.entities.AuditLog.create({
    data: {
      action: "UPDATE",
      entityName: "Document",
      entityId: args.id,
      userId: context.user.id,
      payload: JSON.stringify({ title: args.title, content: args.content }),
    },
  });
};

export const deleteDocument: DeleteDocument<{ id: number }, void> = async (
  args,
  context
) => {
  if (!context.user) {
    throw new HttpError(401, "Authentication required");
  }
  // Only ADMIN can delete documents
  if (context.user.role !== "ADMIN") {
    throw new HttpError(403, "Only ADMIN users can delete documents");
  }

  await context.entities.Document.delete({
    where: { id: args.id },
  });

  // Create audit log entry
  await context.entities.AuditLog.create({
    data: {
      action: "DELETE",
      entityName: "Document",
      entityId: args.id,
      userId: context.user.id,
      payload: JSON.stringify({ id: args.id }),
    },
  });
};

import { login, signup } from "wasp/client/auth";
import { useState } from "react";
import { useNavigate } from "react-router";

export function SignupPage() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [role, setRole] = useState("ANALYST");
  const [error, setError] = useState<Error | null>(null);
  const navigate = useNavigate();

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault();
    setError(null);
    try {
      await signup({ username, password, role });
      await login({ username, password });
      navigate("/");
    } catch (error: unknown) {
      setError(error as Error);
    }
  }

  return (
    <div className="auth-container">
      <h2>Sign Up</h2>
      {error && <div className="error">Error: {error.message}</div>}
      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label htmlFor="username">Username</label>
          <input
            id="username"
            type="text"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            placeholder="Username"
          />
        </div>
        <div className="form-group">
          <label htmlFor="password">Password</label>
          <input
            id="password"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="Password"
          />
        </div>
        <div className="form-group">
          <label htmlFor="role">Role</label>
          <select
            id="role"
            value={role}
            onChange={(e) => setRole(e.target.value)}
          >
            <option value="ANALYST">ANALYST</option>
            <option value="MANAGER">MANAGER</option>
            <option value="ADMIN">ADMIN</option>
          </select>
        </div>
        <button type="submit" id="signup-btn">
          Sign Up
        </button>
      </form>
      <p>
        Already have an account? <a href="/login">Login</a>
      </p>
    </div>
  );
}

