    throw new HttpError(403, "Only MANAGER and ADMIN users can create documents");
  }

  const doc = await context.entities.Document.create({
    data: {
      title: args.title,
      content: args.content,
      ownerId: context.user.id,
    },
  });

  // Create audit log entry
  await context.entities.AuditLog.create({
    data: {
      action: "CREATE",
      entityName: "Document",
      entityId: doc.id,
      userId: context.user.id,
      payload: JSON.stringify({ title: args.title, content: args.content }),
    },
  });
};

export const updateDocument: UpdateDocument<
  { id: number; title: string; content: string },
  void
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Authentication required");
  }
  // Only MANAGER and ADMIN can update documents
  if (context.user.role !== "MANAGER" && context.user.role !== "ADMIN") {
    throw new HttpError(403, "Only MANAGER and ADMIN users can update documents");
  }

  await context.entities.Document.update({
    where: { id: args.id },
    data: {
      title: args.title,
      content: args.content,
    },
  });

  // Create audit log entry
  await context.entities.AuditLog.create({
    data: {
      action: "UPDATE",
      entityName: "Document",
      entityId: args.id,
      userId: context.user.id,
      payload: JSON.stringify({ title: args.title, content: args.content }),
    },
  });
};

export const deleteDocument: DeleteDocument<{ id: number }, void> = async (
  args,
  context
) => {
  if (!context.user) {
    throw new HttpError(401, "Authentication required");
  }
  // Only ADMIN can delete documents
  if (context.user.role !== "ADMIN") {
    throw new HttpError(403, "Only ADMIN users can delete documents");
  }

  await context.entities.Document.delete({
    where: { id: args.id },
  });

  // Create audit log entry
  await context.entities.AuditLog.create({
    data: {
      action: "DELETE",
      entityName: "Document",
      entityId: args.id,
      userId: context.user.id,
      payload: JSON.stringify({ id: args.id }),
    },
  });
};

import { useAuth, logout } from "wasp/client/auth";
import {
  useQuery,
  getDocuments,
  getAuditLogs,
  createDocument,
  updateDocument,
  deleteDocument,
} from "wasp/client/operations";
import { useState } from "react";
import "./Main.css";

export function MainPage() {
  const { data: user } = useAuth();
  const { data: documents, refetch: refetchDocuments } = useQuery(getDocuments);
  const { data: auditLogs, refetch: refetchAuditLogs } = useQuery(getAuditLogs);
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");

  if (!user) {
    return (
      <main className="container">
        <h2>Please log in to access the dashboard.</h2>
        <div className="buttons">
          <a className="button button-filled" href="/login">
            Login
          </a>
          <a className="button button-outlined" href="/signup">
            Sign Up
          </a>
        </div>
      </main>
    );
  }

  const role = user.role || "ANALYST";
  const canCreateUpdate =
    role === "MANAGER" || role === "ADMIN";
  const canDelete = role === "ADMIN";
  const canViewAuditLogs = role === "ADMIN";

  async function handleCreateDoc(e: React.FormEvent) {
    e.preventDefault();
    await createDocument({ title, content });
    setTitle("");
    setContent("");
    refetchDocuments();
  }

  async function handleUpdateDoc(
    id: number,
    currentTitle: string,
    currentContent: string
  ) {
    await updateDocument({
      id,
      title: currentTitle + " (updated)",
      content: currentContent + " (updated)",
    });
    refetchDocuments();
    if (canViewAuditLogs) refetchAuditLogs();
  }

  async function handleDeleteDoc(id: number) {
    await deleteDocument({ id });
    refetchDocuments();
    if (canViewAuditLogs) refetchAuditLogs();
  }

  return (
    <main className="container">
      <div className="header">
        <h1>Enterprise Dashboard</h1>
        <div className="user-info">
          <span className="role-badge">Role: {role}</span>
          <button id="logout-btn" className="button button-outlined" onClick={logout}>
            Logout
          </button>
        </div>
      </div>

      {canCreateUpdate && (
        <section className="section">
          <h2>Create Document</h2>
          <form onSubmit={handleCreateDoc} className="doc-form">
            <div className="form-group">
              <label htmlFor="doc-title">Title</label>
              <input
                id="doc-title"
                type="text"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                placeholder="Document title"
              />
            </div>
            <div className="form-group">
              <label htmlFor="doc-content">Content</label>
              <textarea
                id="doc-content"
                value={content}
                onChange={(e) => setContent(e.target.value)}
                placeholder="Document content"
              />
            </div>
            <button type="submit" id="create-doc-btn" className="button button-filled">
              Create Document
            </button>
          </form>
        </section>
      )}

      <section className="section">
        <h2>Documents</h2>
        {documents && documents.length > 0 ? (
          <div className="doc-list">
            {documents.map((doc) => (
              <div key={doc.id} className="doc-card">
                <h3>{doc.title}</h3>
                <p>{doc.content}</p>
                <div className="doc-actions">
                  {canCreateUpdate && (
                    <button
                      data-testid={`update-doc-btn-${doc.id}`}
                      className="button button-outlined"
                      onClick={() => handleUpdateDoc(doc.id, doc.title, doc.content)}
                    >
                      Update
                    </button>
                  )}
                  {canDelete && (
                    <button
                      data-testid={`delete-doc-btn-${doc.id}`}
                      className="button button-filled"
                      onClick={() => handleDeleteDoc(doc.id)}
                    >
                      Delete
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p>No documents found.</p>
        )}
      </section>

      {canViewAuditLogs && (
        <section className="section">
          <h2>Audit Logs</h2>
          {auditLogs && auditLogs.length > 0 ? (
            <div className="audit-list">
              {auditLogs.map((log) => (
                <div key={log.id} className="audit-item" data-testid="audit-log-item">
                  <p>
                    <strong>Action:</strong> {log.action}
                  </p>
                  <p>
                    <strong>Entity:</strong> {log.entityName}
                  </p>
                  <p>
                    <strong>Entity ID:</strong> {log.entityId}
                  </p>
                  <p>
                    <strong>User ID:</strong> {log.userId}
                  </p>
                  <p>
                    <strong>Payload:</strong> {log.payload}
                  </p>
                  <p className="timestamp">
                    <strong>Timestamp:</strong>{" "}
                    {new Date(log.timestamp).toLocaleString()}
                  </p>
                </div>
              ))}
            </div>
          ) : (
            <p>No audit logs found.</p>
          )}
        </section>
      )}
    </main>
  );
}

import { login, signup } from "wasp/client/auth";
import { useState } from "react";
import { useNavigate } from "react-router";

export function SignupPage() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [role, setRole] = useState("ANALYST");
  const [error, setError] = useState<Error | null>(null);
  const navigate = useNavigate();

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault();
    setError(null);
    try {
      await signup({ username, password, role });
      await login({ username, password });
      navigate("/");
    } catch (error: unknown) {
      setError(error as Error);
    }
  }

  return (
    <div className="auth-container">
      <h2>Sign Up</h2>
      {error && <div className="error">Error: {error.message}</div>}
      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label htmlFor="username">Username</label>
          <input
            id="username"
            type="text"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            placeholder="Username"
          />
        </div>
        <div className="form-group">
          <label htmlFor="password">Password</label>
          <input
            id="password"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="Password"
          />
        </div>
        <div className="form-group">
          <label htmlFor="role">Role</label>
          <select
            id="role"
            value={role}
            onChange={(e) => setRole(e.target.value)}
          >
            <option value="ANALYST">ANALYST</option>
            <option value="MANAGER">MANAGER</option>
            <option value="ADMIN">ADMIN</option>
          </select>
        </div>
        <button type="submit" id="signup-btn">
          Sign Up
        </button>
      </form>
      <p>
        Already have an account? <a href="/login">Login</a>
      </p>
    </div>
  );
}

